    depot = g(("depot_id", "depot", "depot_index"), 0)

    def all_ids():
        if isinstance(instance, dict) and "customers" in instance and isinstance(instance["customers"], list):
            return [c for c in instance["customers"] if c != depot]
        if isinstance(demands, dict):
            return sorted([k for k in demands.keys() if k != depot])
        if isinstance(coords, dict):
            return sorted([k for k in coords.keys() if k != depot])
        if isinstance(demands, list):
            return [i for i in range(len(demands)) if i != depot]
        if isinstance(coords, list):
            return [i for i in range(len(coords)) if i != depot]
        return []

    customers = all_ids()

    def pt(i):
        if coords is None:
            return (0.0, 0.0)
        p = coords[i] if isinstance(coords, dict) else coords[i]
        return (float(p[0]), float(p[1]))

    depot_pt = pt(depot)

    def dem(i):
        if demands is None:
            return 1
        if isinstance(demands, dict):
            return int(demands.get(i, 0))
        return int(demands[i])

    cache = {}

    def dist(a, b):
        if a == b:
            return 0.0
        k = (a, b)
        if k in cache:
            return cache[k]
        pa = depot_pt if a == depot else pt(a)
        pb = depot_pt if b == depot else pt(b)
        dx = pa[0] - pb[0]
        dy = pa[1] - pb[1]
        d = (dx * dx + dy * dy) ** 0.5
        cache[k] = d
        cache[(b, a)] = d
        return d

    def route_load(r):
        s = 0
        for c in r:
            s += dem(c)
        return s

    def route_cost(r):
        if not r:
            return 0.0
        t = dist(depot, r[0])
        for i in range(len(r) - 1):
            t += dist(r[i], r[i + 1])
        return t + dist(r[-1], depot)

    def insert_cost(r, c, pos):
        prev = depot if pos == 0 else r[pos - 1]
        nxt = depot if pos == len(r) else r[pos]
        return dist(prev, c) + dist(c, nxt) - dist(prev, nxt)

    def key(i):
        x, y = pt(i)
        x -= depot_pt[0]
        y -= depot_pt[1]
        ang = 0.0
        if x or y:
            if y >= 0:
                ang = x / (abs(x) + abs(y) + 1e-12)
            else:
                ang = 2.0 + x / (abs(x) + abs(y) + 1e-12)
        return (ang, x * x + y * y, i)

    customers = sorted(customers, key=key)

    routes = []
    cur = []
    cur_load = 0
    for c in customers:
        d = dem(c)
        if capacity and cur and cur_load + d > capacity:
            routes.append(cur)
            cur = [c]
            cur_load = d
        else:
            cur.append(c)
            cur_load += d
    if cur:
        routes.append(cur)

    if capacity:
        repaired = []
        for r in routes:
            if route_load(r) <= capacity:
                repaired.append(r)
            else:
                for c in r:
                    repaired.append([c])
        routes = repaired

    def two_opt(r):
        n = len(r)
        if n < 4:
            return r[:]
        best = r[:]
        best_cost = route_cost(best)
        improved = True
        while improved:
            improved = False
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    cc = route_cost(cand)
                    if cc + 1e-12 < best_cost:
                        best, best_cost = cand, cc
                        improved = True
                        break
                if improved:
                    break
        return best

    def normalize(rs):
        out = []
        for r in rs:
            if r:
                out.append(two_opt(r))
        return out

    routes = normalize(routes)

    def total(rs):
        s = 0.0
        for r in rs:
            s += route_cost(r)
        return s

    improved = True
    while improved:
        improved = False
        base = total(routes)

        # relocate
        best_move = None
        best_delta = 0.0
        for a in range(len(routes)):
            ra = routes[a]
            la = route_load(ra)
            for i, c in enumerate(ra):
                dc = dem(c)
                ra_wo = ra[:i] + ra[i + 1:]
                rem_delta_a = route_cost(ra_wo) - route_cost(ra)
                for b in range(len(routes)):
                    if a == b:
                        continue
                    rb = routes[b]
                    lb = route_load(rb)
                    if capacity and lb + dc > capacity:
                        continue
                    for pos in range(len(rb) + 1):
                        add_delta_b = insert_cost(rb, c, pos)
                        delta = rem_delta_a + add_delta_b
                        if delta < best_delta - 1e-12:
                            best_delta = delta
                            best_move = ("relocate", a, b, i, pos)
        if best_move is not None:
            _, a, b, i, pos = best_move
            c = routes[a][i]
            new_a = routes[a][:i] + routes[a][i + 1:]
            new_b = routes[b][:pos] + [c] + routes[b][pos:]
            new_routes = []
            for idx, r in enumerate(routes):
                if idx == a:
                    if new_a:
                        new_routes.append(two_opt(new_a))
                elif idx == b:
                    if new_b:
                        new_routes.append(two_opt(new_b))
                else:
                    new_routes.append(r)
            routes = new_routes
            improved = True
            continue

        # swap
        best_move = None
        best_delta = 0.0
        for a in range(len(routes)):
            ra = routes[a]
            la = route_load(ra)
            for b in range(a + 1, len(routes)):
                rb = routes[b]
                lb = route_load(rb)
                for i, ca in enumerate(ra):
                    da = dem(ca)
                    for j, cb in enumerate(rb):
                        db = dem(cb)
                        na = la - da + db
                        nb = lb - db + da
                        if capacity and (na > capacity or nb > capacity):
                            continue
                        ra2 = ra[:]
                        rb2 = rb[:]
                        ra2[i] = cb
                        rb2[j] = ca
                        delta = (route_cost(ra2) + route_cost(rb2)) - (route_cost(ra) + route_cost(rb))
                        if delta < best_delta - 1e-12:
                            best_delta = delta
                            best_move = ("swap", a, b, i, j)
        if best_move is not None:
            _, a, b, i, j = best_move
            ra = routes[a][:]
            rb = routes[b][:]
            ra[i], rb[j] = rb[j], ra[i]
            routes[a] = two_opt(ra)
            routes[b] = two_opt(rb)
            improved = True
            continue

        # 2-opt within routes after no inter-route move
        changed = False
        for idx in range(len(routes)):
            nr = two_opt(routes[idx])
            if nr != routes[idx] and route_cost(nr) + 1e-12 < route_cost(routes[idx]):
                routes[idx] = nr
                changed = True
        if changed:
            improved = True
            continue

        # merge/split repair: attempt to remove bad singleton routes into others
        if capacity:
            singles = [i for i, r in enumerate(routes) if len(r) == 1]
            moved = False
            for idx in singles:
                if idx >= len(routes):
                    continue
                c = routes[idx][0]
                dc = dem(c)
                best_ins = None
                best_inc = None
                for b in range(len(routes)):
                    if b == idx:
                        continue
                    rb = routes[b]
                    if route_load(rb) + dc > capacity:
                        continue
                    for pos in range(len(rb) + 1):
                        inc = insert_cost(rb, c, pos)
                        if best_inc is None or inc < best_inc - 1e-12:
                            best_inc = inc
                            best_ins = (b, pos)
                if best_ins is not None:
                    b, pos = best_ins
                    if idx < b:
                        ra = [r for k, r in enumerate(routes) if k not in (idx,)]
                        # rebuild carefully
                        old = routes
                        new_routes = []
                        for k, r in enumerate(old):
                            if k == idx:
                                continue
                            if k == b:
                                nr = r[:pos] + [c] + r[pos:]
                                new_routes.append(two_opt(nr))
                            else:
                                new_routes.append(r)
                        routes = new_routes
                    else:
                        old = routes
                        new_routes = []
                        for k, r in enumerate(old):
                            if k == b:
                                nr = r[:pos] + [c] + r[pos:]
                                new_routes.append(two_opt(nr))
                            elif k == idx:
                                continue
                            else:
                                new_routes.append(r)
                        routes = new_routes
                    moved = True
                    break
            if moved:
                improved = True

    routes = [r for r in routes if r]
    routes = [two_opt(r) for r in routes]
    return routes
